def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator dividing the grid into equally sized regions.
    sep = None
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]) and r == h // 2:
            sep = ("row", r)
            break
    if sep is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and c == w // 2:
                sep = ("col", c)
                break

    if sep[0] == "row":
        i = sep[1]
        a, b = grid[:i], grid[i + 1:]
    else:
        i = sep[1]
        a = [row[:i] for row in grid]
        b = [row[i + 1:] for row in grid]

    def zero_fraction(part):
        cells = [v for row in part for v in row]
        return sum(v == 0 for v in cells) / len(cells)

    mask, data = (a, b) if zero_fraction(a) < zero_fraction(b) else (b, a)
    return [
        [2 if data[r][c] != 0 and mask[r][c] != 0 else 0
         for c in range(len(data[0]))]
        for r in range(len(data))
    ]
